import{_ as s,o as n,c as a,a2 as t}from"./chunks/framework.BS0bAV7E.js";const m=JSON.parse('{"title":"Development environment","description":"","frontmatter":{},"headers":[],"relativePath":"dev/environment.md","filePath":"dev/environment.md"}'),i={name:"dev/environment.md"};function o(l,e,p,c,r,d){return n(),a("div",null,[...e[0]||(e[0]=[t(`<h1 id="development-environment" tabindex="-1">Development environment <a class="header-anchor" href="#development-environment" aria-label="Permalink to &quot;Development environment&quot;">​</a></h1><p>How to go from a fresh machine to hacking on the kernel.</p><h2 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements&quot;">​</a></h2><ul><li>A Linux host (Debian/Ubuntu tested; anything with the packages below works). Windows: WSL2 gives you exactly this environment.</li><li><code>gcc</code> (14.x tested), <code>binutils</code> (ld), <code>nasm</code> 2.16+, <code>xorriso</code>, <code>mtools</code>, <code>grub-common</code> + <code>grub-pc-bin</code> + <code>grub-efi-amd64-bin</code>, <code>python3</code> (3.9+), <code>zip</code>.</li><li>For testing: <code>qemu-system-x86</code>, <code>ovmf</code>, <code>seabios</code>, <code>ipxe-qemu</code>.</li><li>For the E2E suites: Python <code>pexpect</code> (regression, watchdog E2E) and <code>paramiko</code> (SSH E2E).</li></ul><p><code>tools/build.sh</code> verifies the build set and prints the exact Debian package for anything missing; <code>./build.sh --install</code> installs them when you are root. The no-root alternative is <code>tools/install-toolchain.sh</code> (unpacks a relocatable tree and exports <code>OC_TOOLS</code>).</p><h2 id="getting-the-tree" tabindex="-1">Getting the tree <a class="header-anchor" href="#getting-the-tree" aria-label="Permalink to &quot;Getting the tree&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>git clone https://github.com/cubestudio-dev/OpenCubeOS.git</span></span>
<span class="line"><span>cd OpenCubeOS</span></span></code></pre></div><h2 id="sanity-build" tabindex="-1">Sanity build <a class="header-anchor" href="#sanity-build" aria-label="Permalink to &quot;Sanity build&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>./build.sh iso        # kernel + ISO</span></span>
<span class="line"><span>make test             # host unit tests</span></span>
<span class="line"><span>make run-bios         # boot it</span></span></code></pre></div><p>If all three pass, your environment is good. The full bar for a change is in <a href="./../root/CONTRIBUTING.html">CONTRIBUTING.md</a>.</p><h2 id="repository-layout" tabindex="-1">Repository layout <a class="header-anchor" href="#repository-layout" aria-label="Permalink to &quot;Repository layout&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>kernel/    core (sched/syscalls/...), mem (PMM/VMM/heap), lib, crypto, ota</span></span>
<span class="line"><span>boot/      boot.S - the 32-&gt;64-bit entry</span></span>
<span class="line"><span>arch/      arm64/ riscv/ cross-compilation bring-up shells</span></span>
<span class="line"><span>drivers/   16 families: block, nic, usb, snd, input, display, pci,</span></span>
<span class="line"><span>           acpi, i2c, time, wireless, bluetooth, sd, camera, misc, scsi</span></span>
<span class="line"><span>fs/        VFS + ramfs + fat32 + exfat + ext4</span></span>
<span class="line"><span>net/       net_core (stack), ssh, sshd, tls, tcp_cc</span></span>
<span class="line"><span>shell/     the oc&gt; shell + all command modules</span></span>
<span class="line"><span>l1/        the L1 extension surface headers + solib support</span></span>
<span class="line"><span>tui/       the terminal UI engine and apps</span></span>
<span class="line"><span>chinese/   CN console layer (font/encoding/IME)</span></span>
<span class="line"><span>libs/      ld_so.c - the in-tree shared-object loader</span></span>
<span class="line"><span>userprogs/ ring-3 test programs (fork/exec/pipe/... )</span></span>
<span class="line"><span>tools/     build + test + docs generators</span></span>
<span class="line"><span>tests/     host-side unit tests (make test)</span></span>
<span class="line"><span>docs/      this documentation tree</span></span></code></pre></div><h2 id="conventions-that-matter-immediately" tabindex="-1">Conventions that matter immediately <a class="header-anchor" href="#conventions-that-matter-immediately" aria-label="Permalink to &quot;Conventions that matter immediately&quot;">​</a></h2><ul><li><code>-Wall -Wextra -Werror</code> - zero warnings, no exceptions.</li><li>Every file carries the SPDX header.</li><li>Kernel-visible strings are ASCII.</li><li>The command surface only grows (see CONTRIBUTING).</li></ul><h2 id="qemu-recipes" tabindex="-1">QEMU recipes <a class="header-anchor" href="#qemu-recipes" aria-label="Permalink to &quot;QEMU recipes&quot;">​</a></h2><p>Keep these one-liners around:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># quick BIOS boot, serial on stdio</span></span>
<span class="line"><span>qemu-system-x86_64 -m 512 -cdrom build/opencube.iso \\</span></span>
<span class="line"><span>    -netdev user,id=n1 -device e1000,netdev=n1 -serial mon:stdio</span></span>
<span class="line"><span></span></span>
<span class="line"><span># UEFI</span></span>
<span class="line"><span>qemu-system-x86_64 -m 512 -machine q35 -bios /usr/share/ovmf/OVMF.fd \\</span></span>
<span class="line"><span>    -cdrom build/opencube.iso -display none -serial mon:stdio</span></span>
<span class="line"><span></span></span>
<span class="line"><span># with a scratch disk + TUI visible</span></span>
<span class="line"><span>qemu-system-x86_64 -m 512 -cdrom build/opencube.iso \\</span></span>
<span class="line"><span>    -drive file=scratch.qcow2,if=ide -netdev user,id=n1 \\</span></span>
<span class="line"><span>    -device e1000,netdev=n1</span></span>
<span class="line"><span></span></span>
<span class="line"><span># boot log to a file</span></span>
<span class="line"><span>... -serial file:boot.log</span></span></code></pre></div><p><code>make run-bios</code>, <code>make run-uefi</code>, <code>make run-bios-gui</code>, <code>make shot-bios</code> wrap the common ones (including the /etc volume setup).</p>`,18)])])}const u=s(i,[["render",o]]);export{m as __pageData,u as default};
